const biz = inject('IErpInvStockLedgerBiz');
const report = biz.checkStockBalanceConsistency(item.asOfDate, batchChunkCtx.serviceContext);
if (report.mismatchCount > 0) {
    throw new Error('erp-inv-stock-check: 账面余额与流水派生快照不一致，asOfDate=' + report.asOfDate
        + ', mismatchCount=' + report.mismatchCount);
}
